function runMediaSession() {
  // 1. Safely pull PenguinMod's uppercase JSON variables
  const currentTitle = (typeof TITLE !== 'undefined') ? TITLE : "";
  const currentArtist = (typeof ARTIST !== 'undefined') ? ARTIST : "";
  const currentUrl = (typeof ALBUMCOVERURL !== 'undefined') ? ALBUMCOVERURL : "";

  // Set up global tracking state on the browser's window object
  window.dummyMediaState = window.dummyMediaState || {
    title: "",
    artist: "",
    albumCoverUrl: "",
    initialized: false
  };

  // 2. Stop condition
  if (currentTitle === "stop" || currentArtist === "stop") {
    if (window.dummyAudioElement) {
      try {
        window.dummyAudioElement.pause();
        window.dummyAudioElement.src = "";
      } catch(e) {}
    }
    window.dummyAudioElement = null;
    window.dummyMediaState = { title: "", artist: "", albumCoverUrl: "", initialized: false };
    if ('mediaSession' in navigator) {
      navigator.mediaSession.metadata = null;
      navigator.mediaSession.playbackState = "none";
    }
    return;
  }

  // 3. Update state if things have changed
  const hasChanged = 
    currentTitle !== window.dummyMediaState.title || 
    currentArtist !== window.dummyMediaState.artist || 
    currentUrl !== window.dummyMediaState.albumCoverUrl;

  if (hasChanged || !window.dummyMediaState.initialized) {
    window.dummyMediaState.title = currentTitle || "Unknown Title";
    window.dummyMediaState.artist = currentArtist || "Unknown Artist";
    window.dummyMediaState.albumCoverUrl = currentUrl || "";
    window.dummyMediaState.initialized = true;

    if ('mediaSession' in navigator) {
      navigator.mediaSession.metadata = new MediaMetadata({
        title: window.dummyMediaState.title,
        artist: window.dummyMediaState.artist,
        album: 'CuboshNugget',
        artwork: window.dummyMediaState.albumCoverUrl ? [
          { 
            src: window.dummyMediaState.albumCoverUrl, 
            sizes: '500x500', 
            type: 'image/png' 
          }
        ] : []
      });

      navigator.mediaSession.playbackState = "playing";

      // Bind dummy events to satisfy Bluetooth buttons
      const actionHandlers = ['play', 'pause', 'previoustrack', 'nexttrack'];
      for (const action of actionHandlers) {
        try {
          navigator.mediaSession.setActionHandler(action, () => {
            navigator.mediaSession.playbackState = "playing";
          });
        } catch (e) {}
      }
    }

    // 4. Handle background silent audio to wake up the OS media controller
    if (!window.dummyAudioElement) {
      const silentWav = "data:audio/wav;base64,UklGRigAAABXQVZFZm10IBIAAAABAAEARKwAAIhYAQACABAAAABkYXRhAgAAAAEA";
      const audio = new Audio(silentWav);
      audio.loop = true;
      audio.volume = 0.01;

      // Define standard click/interaction event handler to bypass browser blocks
      const startAudio = () => {
        audio.play().then(() => {
          window.removeEventListener('click', startAudio);
          window.removeEventListener('keydown', startAudio);
        }).catch((err) => {
          // Silent catch until user clicks
        });
      };

      window.addEventListener('click', startAudio);
      window.addEventListener('keydown', startAudio);
      startAudio(); // Try playing immediately

      window.dummyAudioElement = audio;
    } else {
      window.dummyAudioElement.play().catch(() => {});
    }
  }
}

// Execute the function at the very end so PenguinMod processes it correctly
runMediaSession();

